import Link from 'next/link';
import { catalogueVisual, type Catalogue } from '@/lib/catalogue';
import styles from './CatalogueArch.module.css';

type Props = {
  catalogue: Catalogue;
  sizes?: string;
  /** Titre de niveau h2 (accueil) ou h3 (sous un h2 existant). */
  as?: 'h2' | 'h3';
};

// Carte d'un catalogue : photo dans une arche, comme les arcades du salon d'exposition.
export default function CatalogueArch({ catalogue, sizes = '(min-width: 900px) 30vw, 80vw', as: Heading = 'h3' }: Props) {
  const img = catalogueVisual(catalogue);
  return (
    <Link href={`/catalogue/${catalogue.slug}`} className={styles.card}>
      <div className={styles.frame}>
        <div className={styles.outline} aria-hidden="true" />
        <div className={styles.arch}>
          {/* eslint-disable-next-line @next/next/no-img-element */}
          <img
            src={img.src}
            srcSet={img.srcSet}
            sizes={sizes}
            width={img.width}
            height={img.height}
            alt=""
            loading="lazy"
            decoding="async"
            className={styles.img}
            style={{ objectPosition: catalogue.visual.position }}
          />
        </div>
        <span className={styles.code}>{catalogue.code}</span>
      </div>
      <div className={styles.text}>
        <Heading className={styles.name}>{catalogue.name}</Heading>
        <p className={styles.specialty}>{catalogue.specialty}</p>
        <p className={styles.more}>
          {catalogue.products.length} modèles
          <span aria-hidden="true" className={styles.arrow}>
            →
          </span>
        </p>
      </div>
    </Link>
  );
}
